// 0x95d89b41 = symbol()

function decodeString(hex) {
  if (!hex || hex === "0x") return "";
  const bytes = Buffer.from(hex.slice(2), "hex");
  // ABI decode string: offset (32 bytes), length (32 bytes), string
  const offset = Number(bytes.readBigUInt64BE(24));
  const length = Number(bytes.readBigUInt64BE(offset + 24));
  return bytes.slice(offset + 32, offset + 32 + length).toString("utf8");
}

